from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_in_denominator():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_pooled_rate_weights_sessions_and_ignores_empty_groups():
    groups = {"a": [{"converted": True}], "b": [{"converted": False}] * 3, "empty": []}
    assert pooled_conversion_rate(groups) == 0.25
    assert pooled_conversion_rate({"empty": []}) == 0.0


@pytest.mark.parametrize(("days", "expected"), [(0, 0), (2, 6), (5, 7)])
def test_conversions_in_window(days, expected):
    assert conversions_in_window([1, 2, 4], days) == expected


def test_parse_session_log_skips_blank_and_comment_lines_and_trims_fields():
    lines = ["", " \t\n", "# comment", "  # indented", " a , 1 , 1 ", " b,2,0", "c,3, "]
    assert parse_session_log(lines) == [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "c", "day": 3, "converted": None},
    ]


@pytest.mark.parametrize("bad_line", ["x,1", "x,1,0,extra", "x,today,1"])
def test_parse_session_log_errors_use_original_line_number(bad_line):
    with pytest.raises(ValueError, match=r"\bline 4\b"):
        parse_session_log([" ", " # comment", "a,1,1", bad_line])


def test_dedupe_keeps_last_record_and_sorts_by_day_then_id():
    earlier = {"id": "b", "day": 5, "converted": True}
    later = {"id": "b", "day": 1, "converted": False}
    same_day = {"id": "a", "day": 1, "converted": True}
    next_day = {"id": "c", "day": 2, "converted": True}
    assert dedupe_sessions([earlier, next_day, later, same_day]) == [same_day, later, next_day]


def test_daily_conversion_counts_fills_gaps_and_ignores_out_of_range_sessions():
    events = parse_session_log(["a,0,1", "b,1,1", "c,1,1", "d,2,", "e,3,0", "f,3,1", "g,4,1"])
    assert daily_conversion_counts(events, 1, 3) == [2, 0, 1]
    assert daily_conversion_counts(events, 3, 1) == []


def test_campaign_summary_uses_calendar_days_and_counts_nonempty_groups():
    groups = {"a": parse_session_log(["a,1,1", "b,3,0"]), "b": parse_session_log(["c,4,"]), "empty": []}
    assert campaign_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert campaign_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert campaign_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_converting_groups_excludes_empty_groups_and_breaks_ties_by_name():
    groups = {"z": [{"converted": True}], "b": [{"converted": False}], "a": [{"converted": True}], "empty": []}
    assert top_converting_groups(groups, 1) == ["a"]
    assert top_converting_groups(groups, 5) == ["a", "z", "b"]


def test_conversion_rate_by_group_orders_keys_and_marks_empty_groups():
    groups = {"z": [], "b": [{"converted": False}], "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups).items()) == [("a", 1.0), ("b", 0.0), ("z", None)]


@pytest.mark.parametrize(("counts", "expected"), [([], 0), ([0, -1], 0), ([2, 1, 0, 3, -1, 4, 1], 2)])
def test_longest_conversion_streak_resets_at_nonpositive_counts(counts, expected):
    assert longest_conversion_streak(counts) == expected
